SELECT a.id AS id, a.id AS activiteit_id, a.productie_id, p.titel AS productie, a.omschrijving, a.soort, a.datum, a.start_at, a.plandag, a.status, COALESCE(a.locatie_id, s.locatie_id) AS locatie_id, CASE WHEN a.locatie_id IS NOT NULL THEN 'eigen' WHEN s.locatie_id IS NOT NULL THEN 'speelreeks' END AS locatie_bron FROM activiteit a JOIN productie p ON p.id = a.productie_id LEFT JOIN speelreeks s ON s.id = a.speelreeks_id AND s.deleted_at IS NULL WHERE a.deleted_at IS NULL
